; 2026-10-16 (runs/maps-pm mkmaps3.py): font-pairing picks 2(TC)=paperfb-paperb-18-aa, 4(TC)=marufb-marub-24-aa, 6(TC)=marufb-marub-20-aa (first in the chain; English original)
# Monkey Island 1 (mi1kor Korean patch). One map, two presets; the ini's
# render_target picks one.
#   Default (true colour: render_target=auto, on DOS rgb565 unless only rgb888 has 640x400; or set rgb565 or rgb888): NanumGothic Bold (NGOTB*) and Gowun Batang Bold (GBATB*) faces, 2 bpp,
#   anti-aliased (blend=auto), baked by tools/korean/scumm-fonts/m1u.tsv:
#   dialogue, verbs and the sentence line in a gothic face, the title/credit
#   card in a serif face. With them in the bare sections, render_target=auto
#   picks true colour.
#   render_target=clut8 (8-bit palette): 1 bpp faces, drawn hard-edged: NEODG16C is a pixel
#   face and NGOTB17 (dialogue) NanumGothic Bold hinted at 17 px, baked by tools/korean/scumm-fonts/m1l.tsv, and the 24 px tall cells (TBGOB24, TBMY24) a real 24 dot
#   DOS Hangul face (Taebaek jamo set, jamoset.py --layout 844-hbios24), 24x24 cells that step as the game's cell does.
# Cells per charset: cs0 22x24, cs1/cs3 16x16, cs2 18x18, cs4 26x24; both
# presets bake the same cells. Charsets that share a cell share one SVF.
# Charset 6 (the Ultimate Talkie verb bar) has no section of its own: the engine lays it out on
# font 0's 11x12 cell and the hi-res layer borrows the nearest cell, cs0's (NGOTB21A/TBGOB24).
# Licences: see NANUMGOT.TXT, GOWUNBAT.TXT, NEODGM.TXT and TAEBAEK.TXT beside this file.
[map]
version=2

[render]
scale=2
blend=auto
[render:clut8]
blend=off

# Every base face holds ASCII and the 2,350 KS X 1001 syllables (the Taebaek and neodgm jamo sets compose all
# 11,172); the X face chained after it, baked by tools/korean/scumm-fonts/m1x.tsv, holds only what the text draws
# beyond that (the syllable outside KS X 1001, the ellipsis and trademark sign the map remaps to). Same cell and
# baseline as its base; the jamo sets need none.
[fonts]
cs0=NGOTB21A.SVF
cs1=NGOTB15.SVF
cs2=NGOTB16B.SVF
cs4=GBATB17B.SVF
cs0x=NGO21AX1.SVF
cs1x=NGO15X1.SVF
cs2x=NGO16BX1.SVF
cs4x=GBA17BX1.SVF
paplb18a=PAPLB18A.SVF
marub24a=MARUB24A.SVF
marub20a=MARUB20A.SVF
[fonts:clut8]
cs0=TBGOB24.SVF
cs1=NEODG16C.SVF
cs2=NGOTB17.SVF
cs4=TBMY24.SVF
cs2x=NGO17X1.SVF
fb=SANGAM16.SVF

# True colour keeps the title/credit card face (GBATB17B, 440 KB) in its file instead of in memory: [load] streams
# it and a glyph is read when it is first drawn (title and credits). GBATB17B.HOT, the characters the game can draw
# with it by tools/korean/charsetchars.py (see SCUMM_FONTS.md), is shipped beside this map but not used: the
# analysis finds about 870 characters, enough to read nearly all of GBATB17B at start and hold 350 KB of it
# (a cache entry keeps two cells), little less than the whole face. [preload] cs4=GBATB17B.HOT turns it on.
# The 8-bit face (TBMY24, 38 KB) stays whole.
[load]
cs4=stream
[load:clut8]
cs4=auto
#[preload]
#cs4=GBATB17B.HOT

[font]
missing=u+25a1
# ASCII from each charset's own SVF (never the game's internal font),
# stepped by the face's own widths
range.basic-latin=same
advance.basic-latin=font
# The baked SVF already sets the baseline the Hangul stands on: drop the game
# glyph's own offsets for Latin and punctuation, or ':' '.' sit low (Indy 4's credits).
origin.basic-latin=face
origin.general-punctuation=face

[font.0]
face=cs0,cs0x
[font.1]
face=cs1,cs1x
[font.2]
face=paplb18a,cs2,cs2x
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.2:clut8]
face=cs2,cs2x
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[font.3]
# the same 16x16 cell as charset 1
face=cs1,cs1x
[font.4]
face=marub24a,cs4,cs4x

# The 8-bit preset chains a supplement only after the dialogue face (charset 2); its other faces are jamo sets.
# fb=SANGAM16.SVF (engine data, SAN10.TXT) ends each chain of a face that lives in the jamo font pack, so a missing
# font pack still shows Korean (16 px; only the 8-bit preset has jamo-set faces).
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.0:clut8]
face=cs0,fb
[font.1:clut8]
face=cs1,fb
[font.3:clut8]
face=cs1,fb
[font.4:clut8]
face=cs4,fb

# An ellipsis on the baseline, not a caret; present in every charset (mi1kor/hires_text.map,
# dumped from the 90x.LFL charsets: "...trailing off^" in the scanned patch text). Real
# punctuation, so it is drawn by the replacement font like any other character.
# 0x0f is the patch's own trademark sign (DISK0N.LEC: "멜레이 섬\x0f!" Mêlée Island™,
# "...보물\x0f", "마스터\x0f" Sword Master), real punctuation too.
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[font.6]
face=marub20a
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.6:clut8]
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[glyphs]
0x5e = u+2026
0x0f = u+2122

# neodgm, the L preset's pixel face, has no ™ glyph; its own 1 bpp 0x0f matches the
# hard-edged L look, so clut8 keeps the game's own glyph instead of falling back to the
# missing-glyph box.
[glyphs:clut8]
0x0f = original

# Solid arrows in the 2 bpp dialogue and card charsets: the game's own glyphs.
# 0x5f is a real underscore elsewhere.
[glyphs.2]
0x5f = original
0x7f = original

[glyphs.4]
0x5f = original
0x7f = original
